  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('lineTotal: calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 9500 };
  assert.equal(lineTotal(line), 47500);
});

test('lineTotal: handles qty of 1', () => {
  const line = { qty: 1, unitPrice: 120000 };
  assert.equal(lineTotal(line), 120000);
});

test('lineTotal: handles large quantities', () => {
  const line = { qty: 1000, unitPrice: 1000 };
  assert.equal(lineTotal(line), 1000000);
});

test('lineTotal: does not mutate input', () => {
  const line = { qty: 5, unitPrice: 9500 };
  const lineCopy = { ...line };
  lineTotal(line);
  assert.deepEqual(line, lineCopy);
});

test('invoiceTotals: sums single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.vat, 9975);
  assert.equal(totals.total, 57475);
});

test('invoiceTotals: sums multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, vatRate: 21 },
      { qty: 1, unitPrice: 120000, vatRate: 21 },
      { qty: 100, unitPrice: 50, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 95000 + 120000 + 5000);
  const expectedVAT = Math.round((95000 * 21) / 100) + Math.round((120000 * 21) / 100) + Math.round((5000 * 21) / 100);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, 220000 + expectedVAT);
});

test('invoiceTotals: returns zero for empty invoice', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals: total includes VAT', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 1000, vatRate: 21 },
      { qty: 2, unitPrice: 2000, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 7000;
  const expectedVAT = Math.round((7000 * 21) / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedSubtotal + expectedVAT);
});

test('invoiceTotals: does not mutate input', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500 }],
  };
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  invoiceTotals(invoice);
  assert.deepEqual(invoice, invoiceCopy);
});

test('invoiceTotals: works with real invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-004',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const expectedSubtotal = 10 * 9500 + 1 * 120000;
  const expectedVAT = Math.round((expectedSubtotal * 21) / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedSubtotal + expectedVAT);
});

test('addLine: adds a new line to invoice', () => {
