test('addLine and removeLine: can add and remove multiple times', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);

  let invoice = result.value;
  let updated = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(updated.ok, true);
  invoice = updated.value;

  updated = addLine(invoice, { sku: 'STICKER', qty: 10 });
  assert.equal(updated.ok, true);
  invoice = updated.value;

  assert.equal(invoice.lines.length, 3);

  updated = removeLine(invoice, 'LOGO-PACK');
  assert.equal(updated.ok, true);
  invoice = updated.value;

  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(invoice.lines[1].sku, 'STICKER');
});

test('issueInvoice: changes status and assigns number', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);

  assert.equal(issued.ok, true);
  assert.equal(issued.value.status, 'issued');
  assert.equal(issued.value.number, 'INV-2025-0001');
});

test('issueInvoice: assigns next number correctly', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, [
    'INV-2025-0001',
    'INV-2025-0002',
  ]);

  assert.equal(issued.ok, true);
  assert.equal(issued.value.number, 'INV-2025-0003');
});

test('issueInvoice: returns NOT_DRAFT if not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'sent',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const issued = issueInvoice(invoice, []);

  assert.equal(issued.ok, false);
  assert.equal(issued.error, 'NOT_DRAFT');
});

test('issueInvoice: does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const invoiceCopy = JSON.parse(JSON.stringify(result.value));

  issueInvoice(result.value, []);

  assert.deepEqual(result.value, invoiceCopy);
});

test('issueInvoice: preserves all invoice fields', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-09-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, ['INV-2025-0001']);

  assert.equal(issued.ok, true);
  assert.equal(issued.value.customerId, 'C-002');
  assert.equal(issued.value.issueDate, '2025-09-15');
  assert.equal(issued.value.lines.length, 2);
  assert.equal(issued.value.number, 'INV-2025-0002');
  assert.equal(issued.value.status, 'issued');
});

test('issueInvoice: works after modifying invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  let invoice = result.value;

  const added = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(added.ok, true);
  invoice = added.value;

  const issued = issueInvoice(invoice, []);

  assert.equal(issued.ok, true);
  assert.equal(issued.value.status, 'issued');
  assert.equal(issued.value.number, 'INV-2025-0001');
  assert.equal(issued.value.lines.length, 2);
});

