    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 15000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 2100 + 450);
  assert.equal(totals.total, 15000 + 2550);
});

test('invoiceTotals: calculates total correctly with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  const subtotal = 100000;
  const discount = 10000;
  const amount = subtotal - discount;
  const vat = Math.round((amount * 21) / 100);
  const total = subtotal - discount + vat;

  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, total);
});

